const letters = ["A","B","C","D"] as const;
function makeQuiz(qs:string[][]):NewsQuestion[]{return qs.map(([question,right,...wrong],i)=>{const pos=[2,0,3,1,2][i];const arr=wrong.slice();arr.splice(pos,0,right);return {question,options:arr as NewsQuestion["options"],correct:letters[pos]};});}
export const CREATOR_READS:NewsArticle[]=drafts.map(a=>({slug:a.slug,kind:"feature",section:"Biography",title:a.title,dek:a.dek,grades:"Grades 4–8",publishedOn:"2026-10-22",photo:{wikipediaTitle:a.wiki,alt:"Photograph of "+a.name},sources:a.source.map(url=>({name:new URL(url).hostname,url})),body:a.body.split(/\n\n/).map(t=>t.startsWith("## ")?{kind:"h" as const,text:t.slice(3)}:{kind:"p" as const,text:t}),words:a.words.map(([word,meaning])=>({word,meaning})),questions:makeQuiz(a.qa)}));
